SELECT percentile_cont(0.5) within GROUP (ORDER BY los) AS p50, percentile_cont(0.75) within GROUP (ORDER BY los) AS p75, percentile_cont(0.90) within GROUP (ORDER BY los) AS p90, percentile_cont(0.95) within GROUP (ORDER BY los) AS p95 FROM admissions WHERE subject_id IN (SELECT subject_id FROM admissions_52_62) AND subject_id IN (SELECT subject_id FROM patient_57) AND dischtime IS NOT NULL AND deathtime IS NULL; SELECT percent_rank() within GROUP (ORDER BY los) AS percentile_rank_7_days FROM admissions WHERE subject_id IN (SELECT subject_id FROM admissions_52_62) AND subject_id IN (SELECT subject_id FROM patient_57) AND dischtime IS NOT NULL AND (dischtime - intime) <= 7;